photos = {}
for slug, (city, lat, lon, title, _) in cities.items():
    params = {'action':'query','format':'json','titles':f'File:{title}','prop':'imageinfo','iiprop':'url|size|extmetadata','iiurlwidth':'1000'}
    req = urllib.request.Request('https://commons.wikimedia.org/w/api.php?'+urllib.parse.urlencode(params), headers={'User-Agent':UA})
    data = json.load(urllib.request.urlopen(req, timeout=30))
    page = next(iter(data.get('query',{}).get('pages',{}).values()))
    info = page['imageinfo'][0]
    source_url = info.get('descriptionurl') or 'https://commons.wikimedia.org/wiki/'+urllib.parse.quote('File:'+title)
    meta = info.get('extmetadata', {})
    credit = re.sub('<[^>]+>', '', meta.get('Artist',{}).get('value','')).strip() or 'Wikimedia Commons contributor'
    license_name = meta.get('LicenseShortName',{}).get('value','').strip() or 'See source page'
    thumb = info.get('thumburl') or info.get('url')
    raw = urllib.request.urlopen(urllib.request.Request(thumb, headers={'User-Agent':UA}), timeout=60).read()
    image = Image.open(BytesIO(raw)).convert('RGB')
    image.thumbnail((640,420), Image.Resampling.LANCZOS)
    filename = f'{slug}-{re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")[:35]}.webp'
    out = PUBLIC / filename
    image.save(out, 'WEBP', quality=74, method=6)
    photos[slug] = (f'/tourism/{filename}', source_url, credit, license_name, title, out.stat().st_size, image.size)


def esc(s: str) -> str:
    return s.replace('\\','\\\\').replace('"','\\"').replace('\n',' ')

lines = ["import type { TourismSpot } from './tourism';", '', 'const sourceLabel = \'راهنمای گردشگری و ویکی‌پدیای فارسی\';', '', 'const makeSpot = (city: string, cityLat: number, cityLon: number, item: { id: string; name: string; category: TourismSpot[\'category\']; description: string; duration: string; icon: string; accent: string; imageUrl?: string; imageSourceUrl?: string; imageCredit?: string; imageLicense?: string }, index: number): TourismSpot => ({', '  ...item,', '  latitude: cityLat + index * 0.004,', '  longitude: cityLon + index * 0.004,', "  tip: 'ساعت بازدید و وضعیت دسترسی را پیش از حرکت بررسی کنید و به محیط و حریم جاذبه احترام بگذارید.',", '  locationLabel: city,', "  sourceUrl: `https://fa.wikipedia.org/wiki/${encodeURIComponent(city)}`,", '  sourceLabel,', '});', '', 'export const tourismBatch2: Record<string, TourismSpot[]> = {']
icons = ['🏛️','🌿','🍽️']
accents = ['#b45309','#15803d','#7c3aed']
for slug, (city, lat, lon, title, items) in cities.items():
    lines.append(f'  "{slug}": [')
    for i,(name,cat,desc,duration) in enumerate(items):
        extra = ''
        if i == 0:
            p = photos[slug]
            extra = f', imageUrl: "{p[0]}", imageSourceUrl: "{esc(p[1])}", imageCredit: "{esc(p[2])}", imageLicense: "{esc(p[3])}"'
        lines.append(f'    makeSpot("{esc(city)}", {lat}, {lon}, {{ id: "{slug}-{i+1}", name: "{esc(name)}", category: "{cat}", description: "{esc(desc)}", duration: "{duration}", icon: "{icons[i]}", accent: "{accents[i]}"{extra} }}, {i}),')
    lines.append('  ],')
lines += ['};','']
TS_OUT.write_text('\n'.join(lines), encoding='utf-8')

with ATTR.open('a', encoding='utf-8') as f:
    f.write('\n## تصاویر مرحلهٔ سوم؛ ۲۰ شهر تکمیل‌شده\n\n')
    for slug, p in photos.items():
        f.write(f'- `{Path(p[0]).name}` — [{p[4]}]({p[1]}), {p[2]}, {p[3]}; بهینه‌شده با WebP ({p[5]:,} bytes).\n')

print(f'generated {TS_OUT} and {len(photos)} images')
for slug,p in photos.items(): print(slug, p[0], p[5], p[6])
